struct Positions {
    std::vector<double> price;
    std::vector<int> quantity;
    // other fields live in their own parallel arrays
};
Positions positions;

double totalExposure() {
    double total = 0.0;
    for (size_t i = 0; i < positions.price.size(); ++i)
        total += positions.price[i] * positions.quantity[i];
    return total;
}

