class PriceMatrix {
public:
    PriceMatrix(size_t rows, size_t cols)
        : rows_(rows), cols_(cols), data_(new double[rows * cols]) {}

    // Move constructor: steal the buffer, leave source empty
    PriceMatrix(PriceMatrix&& other) noexcept
        : rows_(other.rows_), cols_(other.cols_), data_(other.data_) {
        other.data_ = nullptr;
        other.rows_ = other.cols_ = 0;
    }

    // Move assignment: release our own buffer first, then steal
    PriceMatrix& operator=(PriceMatrix&& other) noexcept {
        if (this != &other) {
            delete[] data_;
            data_ = other.data_;
            rows_ = other.rows_;
            cols_ = other.cols_;
            other.data_ = nullptr;
            other.rows_ = other.cols_ = 0;
        }
        return *this;
    }

    ~PriceMatrix() { delete[] data_; }  // safe: nullptr delete is a no-op

    PriceMatrix(const PriceMatrix&) = delete;            // disable copy for this example
    PriceMatrix& operator=(const PriceMatrix&) = delete;

private:
    size_t rows_, cols_;
    double* data_;
};

// Buggy: captures a stack local by reference, then outlives it
std::function<bool(double)> makeRiskCheck(double limit) {
    return [&limit](double exposure) { return exposure <= limit; };
}  // 'limit' is destroyed here -- the returned lambda now dangles

RiskMonitor monitor;
monitor.check = makeRiskCheck(5'000'000.0);  // stored for later use
// ... later, monitor.check(exposure) reads a dangling reference

// Fixed: capture by value -- the lambda owns its own independent copy
std::function<bool(double)> makeRiskCheck(double limit) {
    return [limit](double exposure) { return exposure <= limit; };
}

class RiskLimitsLock {
public:
    explicit RiskLimitsLock(std::mutex& m) : mutex_(m) { mutex_.lock(); }
    ~RiskLimitsLock() { mutex_.unlock(); }   // runs even if an exception unwinds through here

    RiskLimitsLock(const RiskLimitsLock&) = delete;
    RiskLimitsLock& operator=(const RiskLimitsLock&) = delete;

private:
    std::mutex& mutex_;
};

void updateLimit(std::mutex& m, std::map<std::string, double>& limits,
                  const std::string& symbol, double newLimit) {
    RiskLimitsLock guard(m);          // locked here
    if (newLimit < 0.0) throw std::invalid_argument("negative limit");
    limits[symbol] = newLimit;
}   // guard's destructor unlocks here -- on normal return OR exception unwind

std::vector<Order> loadOrderBatch(const std::vector<RawFeedMessage>& feed) {
    std::vector<Order> orders;
    orders.reserve(feed.size());   // one allocation, not several reallocate-and-copy cycles

    for (const auto& msg : feed) {
        // emplace_back constructs the Order in place -- no temporary to copy or move
        orders.emplace_back(msg.symbol, msg.quantity, msg.price);
    }
    return orders;   // return by value is a move (RVO/NRVO), not a copy
}

#include <pybind11/pybind11.h>
#include <pybind11/numpy.h>

namespace py = pybind11;

py::array_t<double> callPayoff(py::array_t<double> spots, double strike) {
    py::buffer_info buf = spots.request();
    if (buf.ndim != 1) throw std::runtime_error("expected a 1-D array");

    auto result = py::array_t<double>(buf.shape);      // one new allocation
    py::buffer_info resBuf = result.request();

    const double* in  = static_cast<const double*>(buf.ptr);     // reads NumPy's own buffer
    double*       out = static_cast<double*>(resBuf.ptr);        // writes directly into result's buffer

    for (ssize_t i = 0; i < buf.shape[0]; ++i) {
        double payoff = in[i] - strike;
        out[i] = payoff > 0.0 ? payoff : 0.0;
    }
    return result;
}

PYBIND11_MODULE(quantlib_cpp, m) {
    m.def("call_payoff", &callPayoff, py::arg("spots"), py::arg("strike"));
}

import pandas as pd

def crossover_signal(price: pd.Series, fast_window: int, slow_window: int) -> pd.Series:
    fast = price.rolling(fast_window).mean()
    slow = price.rolling(slow_window).mean()
    raw_signal = (fast > slow).astype(int)          # 1 = long, 0 = flat
    # Critical: shift by 1 bar -- today's signal can only be ACTED ON tomorrow,
    # since today's close (used to compute fast/slow) isn't known until the close happens.
    return raw_signal.shift(1)

def backtest_returns(price: pd.Series, fast_window: int, slow_window: int) -> pd.Series:
    position = crossover_signal(price, fast_window, slow_window)
    daily_return = price.pct_change()
    return (position * daily_return).fillna(0)
